<p class="mb-4 text-dark-600 dark:text-dark-300 leading-relaxed">A psychiatrist is a medical doctor specializing in mental health who can diagnose mental disorders, evaluate medical factors, prescribe medication, and provide other psychiatric treatment. A psychologist is a mental-health professional whose work may include psychological assessment and psychotherapy, depending on their qualifications and scope of practice. Psychiatrists can also provide psychotherapy. Some people benefit from seeing both professionals.</p>
